"sentences selected and shortened", "licence_url": "https://creativecommons.org/licenses/by-sa/4.0/"}, "desc_sha256": "9cf84b4c8d3c4473f1400c75fa3dfb159ea180d33c37bac2534b7a6269156271"}}', 'teaser-prov-s038-rollback:fa2037ed-54b7-425a-9650-27f0e25ac274:raw_data', 'rollback of teaser-prov-s038: raw_data ''{"_card_provenance": {"v": 2, "ai": "generated", "run": "wb-ws-2026-09-27-06", "kind": "teaser", "lane": "WB", "check": {"at": "2026-09-30T06:25:21+00:00", "by": "teaser-wb-ws-2026-09-27-06-check1-003", "stage": "check1", "claims": [{"claim": "the avenue was curving", "support": ["S1"]}, {"claim": "the avenue ran from Avebury towards The Longstones", "support": ["S1"]}, {"claim": "only one stone of the avenue still stands", "support": ["S3"]}, {"claim": "the standing stone is called Adam", "support": ["S3"]}, {"claim": "excavations took place in 2000", "support": ["S5"]}, {"claim": "the excavations revealed parallel rows of holes", "support": ["S5"]}, {"claim": "the holes held the avenue\''s stones", "support": ["S5"]}], "verdict": "PASS"}, "verify": {"at": "2026-09-30T07:32:57+00:00", "by": "teaser-wb-ws-2026-09-27-06-verify-087", "stage": "verify", "claims": 7, "verdict": "VERIFIED", "unproven": 0, "text_sha256": "ef2dcf6462aee78492548a584c4db3346e4c444e22b64473c82aef723ab83ef4"}, "ai_system": "Claude Opus and Claude Sonnet (Anthropic): anthropic/claude-opus-5-5 and anthropic/claude-sonnet-5-5 (Claude Code agents), an-sites-remediation-2026-09", "web_facts": [], "desc_sha256": "9cf84b4c8d3c4473f1400c75fa3dfb159ea180d33c37bac2534b7a6269156271", "text_sha256": "ef2dcf6462aee78492548a584c4db3346e4c444e22b64473c82aef723ab83ef4"}, "description_citations": [{"n": 1, "url": "https://en.wikipedia.org/w/index.php?title=Beckhampton_Avenue&oldid=1364476413", "title": "Wikipedia: Beckhampton Avenue", "domain": "en.wikipedia.org", "license": "CC BY-SA 4.0"}], "_description_provenance": {"v": 1, "ai": "selected", "run": "v3-2026-09-26", "card": null, "lane": "W", "licence": "CC BY-SA 4.0", "sources": [{"id": "W", "url": "https://en.wikipedia.org/w/index.php?title=Beckhampton_Avenue&oldid=1364476413", "revid": 1364476413, "licence": "CC BY-SA 4.0", "text_sha256": "059d2324ce5ce1870b07aac18b0d36e7a6baf9434f9bfb46c2df2d45a1df9e0e", "rev_timestamp": "2026-07-16T20:03:58Z"}], "ai_system": "Claude Opus (Anthropic): anthropic/claude-opus-5-5 (Claude Code agent), an-sites-remediation-2026-09", "sentences": [{"n": 1, "end": 180, "src": "W", "drop": [], "start": 0}, {"n": 1, "end": 242, "src": "W", "drop": [], "start": 181}, {"n": 1, "end": 425, "src": "W", "drop": [[348, 369]], "start": 263}, {"n": 1, "end": 521, "src": "W", "drop": [], "start": 426}, {"n": 1, "end": 642, "src": "W", "drop": [], "start": 522}, {"n": 1, "end": 842, "src": "W", "drop": [[653, 662], [776, 784]], "start": 643}, {"n": 1, "end": 1434, "src": "W", "drop": [], "start": 1342}], "attribution": {"url": "https://en.wikipedia.org/w/index.php?title=Beckhampton_Avenue&oldid=1364476413", "title": "Beckhampton Avenue", "changes": "sentences selected and shortened", "licence_url": "https://creativecommons.org/licenses/by-sa/4.0/"}, "desc_sha256": "9cf84b4c8d3c4473f1400c75fa3dfb159ea180d33c37bac2534b7a6269156271"}}'' restored on Beckhampton Avenue', '9cf84b4c8d3c4473f1400c75fa3dfb159ea180d33c37bac2534b7a6269156271', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Parallel rows of holes show where the stones of this prehistoric line once stood. Excavation uncovered 120 metres of a double row, with the stones placed at 15 metres intervals."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "parallel rows of holes were found [S5]; the holes held the stones of the monument [S5]; the monument is a prehistoric line (avenue) of stones [S1]; excavation uncovered 120 metres of it [S6]; it was a double row of stones [S6]; the stones were placed at 15-metre intervals [S6]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Parallel rows of holes show where the stones of the Beckhampton Avenue once stood. [SUPPORTED: https://www.bristol.ac.uk/news/2007/11920111227.html]; The stones of the avenue no longer stand where they once stood (they are gone). [SUPPORTED: https://www.bristol.ac.uk/news/2007/11920111227.html]; The Beckhampton Avenue is a prehistoric line (avenue) of stones. [SUPPORTED: https://researchframeworks.org/stonehengeavebury/avebury-resource-assessment-part-two-period-based-assessments/]; Excavation uncovered 120 metres of the avenue. [SUPPORTED: https://www.bristol.ac.uk/news/2007/11920111227.html]; The uncovered stretch was a double row of stones. [SUPPORTED: https://www.bristol.ac.uk/news/2007/11920111227.html]; The stones were placed at 15-metre intervals. [SUPPORTED: https://www.bristol.ac.uk/news/2007/11920111227.html]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 16;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_prov_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'raw_data' THEN p.new_value::jsonb IS NOT DISTINCT FROM p.old_value::jsonb OR p.old_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.old_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_prov_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_prov_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/card-provenance', 'wb-teaser-prov-s038-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card provenance: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.new_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-prov-s038-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-prov-s038-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('raw_data'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: this run stamp journalled % row(s) outside unified_sites.(raw_data)', bad;
    END IF;

    RAISE NOTICE 'teaser card provenance: % of % planned cell(s) changed and journalled over 16 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-prov-s038-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/card-provenance'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-prov-s038-rollback' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('raw_data')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'raw_data' THEN u.raw_data IS NOT DISTINCT FROM l.new_value::jsonb
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
